queries.sphinxql:
CREATE TABLE gh5082_columnar (s string attribute, b bool, c string attribute) engine='columnar';
CREATE TABLE gh5082_mixed (s string attribute, b bool engine='columnar', c string attribute engine='columnar');
INSERT INTO gh5082_columnar (id,s,b,c) VALUES (1,'a',1,'red'),(2,'a',0,'blue'),(3,'b',1,'red'),(4,'b',1,'red');
INSERT INTO gh5082_mixed (id,s,b,c) VALUES (1,'a',1,'red'),(2,'a',0,'blue'),(3,'b',1,'red'),(4,'b',1,'red');
SELECT s, b AS x, COUNT(*) AS n FROM gh5082_columnar GROUP BY s, x ORDER BY s ASC, x ASC;
SELECT s, b AS x, COUNT(*) AS n FROM gh5082_columnar GROUP BY s, b ORDER BY s ASC, x ASC;
SELECT s, b AS x, COUNT(*) AS n FROM gh5082_columnar GROUP BY x, s ORDER BY s ASC, x ASC;
SELECT s, c AS x, COUNT(*) AS n FROM gh5082_columnar GROUP BY s, x ORDER BY s ASC, x ASC;
SELECT s AS y, b AS x, COUNT(*) AS n FROM gh5082_columnar GROUP BY y, x ORDER BY y ASC, x ASC;
SELECT s, b AS x, COUNT(*) AS n FROM gh5082_mixed GROUP BY s, x ORDER BY s ASC, x ASC;
SELECT s, c AS x, COUNT(*) AS n FROM gh5082_mixed GROUP BY s, x ORDER BY s ASC, x ASC;
FLUSH RAMCHUNK gh5082_columnar;
FLUSH RAMCHUNK gh5082_mixed;
SELECT s, b AS x, COUNT(*) AS n FROM gh5082_columnar GROUP BY s, x ORDER BY s ASC, x ASC;
SELECT s, c AS x, COUNT(*) AS n FROM gh5082_columnar GROUP BY s, x ORDER BY s ASC, x ASC;
SELECT s, b AS x, COUNT(*) AS n FROM gh5082_mixed GROUP BY s, x ORDER BY s ASC, x ASC;
SELECT s, c AS x, COUNT(*) AS n FROM gh5082_mixed GROUP BY s, x ORDER BY s ASC, x ASC;
INSERT INTO gh5082_columnar (id,s,b,c) VALUES (5,'a',1,'red'),(6,'c',0,'blue');
INSERT INTO gh5082_mixed (id,s,b,c) VALUES (5,'a',1,'red'),(6,'c',0,'blue');
SELECT s, b AS x, COUNT(*) AS n FROM gh5082_columnar GROUP BY s, x ORDER BY s ASC, x ASC OPTION threads=4;
SELECT s, c AS x, COUNT(*) AS n FROM gh5082_mixed GROUP BY s, x ORDER BY s ASC, x ASC OPTION threads=4;
FLUSH RAMCHUNK gh5082_columnar;
FLUSH RAMCHUNK gh5082_mixed;
SELECT s, b AS x, COUNT(*) AS n FROM gh5082_columnar GROUP BY s, x ORDER BY s ASC, x ASC OPTION threads=4;
SELECT s, c AS x, COUNT(*) AS n FROM gh5082_columnar GROUP BY s, x ORDER BY s ASC, x ASC OPTION threads=4;
SELECT s, b AS x, COUNT(*) AS n FROM gh5082_mixed GROUP BY s, x ORDER BY s ASC, x ASC OPTION threads=4;
SELECT s, c AS x, COUNT(*) AS n FROM gh5082_mixed GROUP BY s, x ORDER BY s ASC, x ASC OPTION threads=4;
DROP TABLE gh5082_columnar;
DROP TABLE gh5082_mixed;
